/**
 * Dynamic, center-biased GPU mesh surface sampler using TSL.
 *
 * **Overview**
 * This class provides a specialized sampling strategy that concentrates points around a moving center in world space.
 * It is ideal for effects like:
 * - **Footstep Dust**: Spawning particles only near the character's feet.
 * - **Impact Debris**: Concentrating geometry at collision points.
 * - **Local Detail**: Adding high-density details (grass, pebbles) only where the camera is looking.
 *
 * **Mechanism**
 * 1. **Candidate Search**: Per-frame, it builds a list of triangles within a radius of the target center.
 * 2. **Blue Noise Sampling**: Samples points on these triangles using stable blue noise to minimize temporal flickering.
 * 3. **Hysteresis**: Uses a slightly larger radius for retention to prevent popping as the center moves.
 *
 * **Example: Footstep dust particles**
 *
 * ```js
 * import { ComputeMeshDynamicSurfaceSampler } from '@three-blocks/core';
 * import * as THREE from 'three/webgpu';
 *
 * // Create terrain mesh
 * const terrain = new THREE.Mesh(terrainGeometry, terrainMaterial);
 *
 * // Create sampler that follows a character
 * const sampler = new ComputeMeshDynamicSurfaceSampler(terrain, 'position', {
 *   renderer,
 *   count: 2048,
 *   seed: 42
 * });
 *
 * // Create dust particles using InstancedMesh
 * const dustGeometry = new THREE.PlaneGeometry(0.1, 0.1);
 * const dustMaterial = new THREE.SpriteNodeMaterial({ transparent: true });
 * const dustMesh = new THREE.InstancedMesh(dustGeometry, dustMaterial, 2048);
 * dustMesh.instanceMatrix = sampler.outputs.matrix;
 * scene.add(dustMesh);
 *
 * // Update loop - follow character position
 * function animate() {
 *   sampler.setCenter(character.position.x, character.position.y, character.position.z);
 *   sampler.setRadius(3.0);
 *   sampler.setObjectMatrix(terrain.matrixWorld);
 *   sampler.compute();
 * }
 * ```
 *
 * **Example: Dynamic geometry (GPU-animated mesh)**
 *
 * ```js
 * // For meshes with GPU-updated positions (e.g., cloth, water simulation)
 * const sampler = new ComputeMeshDynamicSurfaceSampler(animatedMesh, 'position', {
 *   renderer,
 *   count: 1024
 * });
 *
 * // Enable dynamic mode - rebuilds face data every frame
 * sampler.setDynamicGeometry(true);
 *
 * // Adjust sampling density and area weighting
 * sampler.uDensity.value = 2.0;        // Increase sample density
 * sampler.uAreaPow.value = 0.5;        // Less area bias (more uniform)
 * sampler.uHysteresis.value = 2.0;     // Retention distance for smooth transitions
 * ```
 *
 * @class ComputeMeshDynamicSurfaceSampler
 * @category Compute
 * @tags WebGPU
 * @demo docs/demos/dynamic-surface-sampler.html
 * @private
 */
export class ComputeMeshDynamicSurfaceSampler {
    /**
     * Create a new dynamic surface sampler.
     *
     * @param {THREE.Mesh} mesh - Source mesh to sample from.
     * @param {string} [attributeName='position'] - Name of the position attribute to use.
     * @param {Object} options - Configuration options.
     * @param {THREE.WebGPURenderer} options.renderer - WebGPU renderer instance.
     * @param {number} options.count - Maximum number of samples to generate.
     * @param {number} [options.seed=1337] - Random seed for stable sampling.
     * @param {boolean} [options.useVertexNormals=true] - Whether to interpolate vertex normals or compute face normals.
     */
    constructor(mesh: THREE.Mesh, attributeName?: string, options: {
        renderer: THREE.WebGPURenderer;
        count: number;
        seed?: number;
        useVertexNormals?: boolean;
    });
    renderer: THREE.WebGPURenderer;
    count: number;
    uResampleIndex: any;
    uSeed: any;
    uCenter: any;
    uRadius: any;
    uObjectMatrix: any;
    uFalloffExp: any;
    uHysteresis: any;
    uMaxArea: any;
    uAreaPow: any;
    uDensity: any;
    uMicroDensity: any;
    TRI_COUNT: number;
    indexSSBO: any;
    positionSSBO: any;
    POS_COUNT: any;
    normalSSBO: any;
    faceDataSSBO: any;
    candidateHeaderSSBO: any;
    survivorHeaderSSBO: any;
    outPosSSBO: any;
    outNrmSSBO: any;
    outMatSSBO: any;
    assignedOrderSSBO: any;
    rebuildFaceData: any;
    _geometryDirty: boolean;
    _dynamicGeometry: boolean;
    uGeomTransform: any;
    transformGeometry: any;
    sortPairsIA: any;
    _bitonic: ComputeBitonicSort;
    fillSortPairs: any;
    clearHeader: any;
    clearSurvivors: any;
    buildCandidates: any;
    sampleFromCandidates: any;
    _compiled: boolean;
    /** Center position in world space */
    setCenter(x: any, y: any, z: any): this;
    /** Radius in world units */
    setRadius(r: any): this;
    /** World matrix for the source mesh (if different from identity) */
    setObjectMatrix(mat4: any): this;
    get outputs(): {
        position: any;
        normal: any;
        matrix: any;
    };
    /**
   * Recompute around current center/radius.
   * @param {Object} [options]
   * @param {number} [options.resampleIndex]
   */
    compute(options?: {
        resampleIndex?: number;
    }): void;
    readback(): Promise<{
        positions: Float32Array<any>;
        normals: Float32Array<any>;
    }>;
    /** @returns {Promise<number>} */
    readSurvivorCountAsync(): Promise<number>;
    /** Force rebuild of face centers/areas from current positions on GPU. */
    rebuildFaceDataAsync(): Promise<void>;
    /** Enable per-frame face-data rebuild for dynamic geometry updated on GPU. */
    setDynamicGeometry(enabled?: boolean): this;
}
import { ComputeBitonicSort } from '../Compute/ComputeBitonicSort.js';
